import { basicSetup } from 'codemirror';
import { EditorState, Compartment, StateEffect, StateField } from '@codemirror/state';
import { EditorView, Decoration, keymap } from '@codemirror/view';
import { autocompletion, startCompletion, closeBrackets, completionKeymap } from '@codemirror/autocomplete';
import { StreamLanguage, syntaxHighlighting, HighlightStyle } from '@codemirror/language';
import { tags } from '@lezer/highlight';
import { vim, Vim } from '@replit/codemirror-vim';
import { createIcons, Layers, ArrowRight, Play, Pause, SkipBack, ChevronRight, ChevronDown, Check, Command, BookOpen, Lightbulb, Volume2, VolumeX, Settings2, FlaskConical, X, RotateCcw, CornerDownLeft, Search, Unplug, Radio, Sparkles, ExternalLink, Maximize2, Download, Upload, Save } from 'lucide';
import './style.css';

type Value = { type: string; text: string; items?: Value[] };
type Frame = { stack: Value[]; fuel: number; op: string | null; error: string | null; quoting?: boolean };
type Row = { input: Value[]; target: Value[]; frames: Frame[]; matched: boolean; error: string | null; fuel: number; max_depth: number; output: string };
type Trace = { tokens: { op: string; start: number; end: number; macro?: string }[]; examples: Row[]; matches: number; count: number; primitive_count: number; fuel: number; max_depth: number };
type Example = { input: unknown; output: unknown };
type Lesson = { id: string; title: string; chapter: string; concept: string; story: string; goal: string; starter: string; examples: Example[]; hints: string[]; discovery: string; review: string[]; prediction: string | null; macros: boolean; source: string; extra_tests: number; hint_count: number; primitive_count?: number };
type Op = { name: string; group: string; effect: string; description: string };
type Macro = { name: string; body: string; group: string; expanded: string };
type SavedLesson = { code?: string; solved?: boolean; assisted?: boolean; attempts?: number; hints?: number; note?: string; saved?: string; prediction?: string; reviewed?: number };
type SaveData = { version: number; lesson: string; lessons: Record<string, SavedLesson>; sound: boolean; vim: boolean; motion: boolean; examples: Example[]; shelf: { name: string; code: string }[]; customName: string };
type Model = { ready: boolean; loading: boolean; error?: string; checkpoint?: string; note?: string };
type Verify = { passed: boolean; shown: number; shown_count: number; extra: number; extra_count: number; failures: Row[]; evidence: string };
const $ = <T extends HTMLElement = HTMLElement>(q: string) => document.querySelector<T>(q)!;
const esc = (s: unknown) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!));
const ic = (name: string, cls = '') => `<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const icons = () => createIcons({ icons: { Layers, ArrowRight, Play, Pause, SkipBack, ChevronRight, ChevronDown, Check, Command, BookOpen, Lightbulb, Volume2, VolumeX, Settings2, FlaskConical, X, RotateCcw, CornerDownLeft, Search, Unplug, Radio, Sparkles, ExternalLink, Maximize2, Download, Upload, Save } });
const KEY = 'signal-house.v1';
const defaults: SaveData = { version: 1, lesson: 'first-light', lessons: {}, sound: false, vim: true, motion: true, examples: [{ input: [[1, 2, 3]], output: [6] }, { input: [[-2, 5]], output: [3] }, { input: [[]], output: [0] }], shelf: [], customName: 'Untitled experiment' };
let saved: SaveData;
try { saved = { ...defaults, ...JSON.parse(localStorage.getItem(KEY) || '{}') }; } catch { saved = structuredClone(defaults); }
let lessons: Lesson[] = [], ops: Op[] = [], macros: Macro[] = [], worlds: Lesson[] = [], model: Model = { ready: false, loading: false };
let trace: Trace | null = null, frame = 0, activeExample = 0, requestId = 0, pending = false, parseError = '', playing: ReturnType<typeof setInterval> | null = null;
let selectedOp = 'add', shelfTab = 'words', hintText = '', verification: Verify | null = null, worldAvailable = 183;
let completionTimer: ReturnType<typeof setTimeout>, evalTimer: ReturnType<typeof setTimeout>, previewSerial = 0, adviserSerial = 0;
let lastFocused: HTMLElement | null = null, commandIndex = 0, focusPrefix = false;
const vimConfig = new Compartment();
const markEffect = StateEffect.define<{ start: number; end: number } | null>();
const markField = StateField.define({ create: () => Decoration.none, update(deco, transaction) { deco = deco.map(transaction.changes); for (const e of transaction.effects) if (e.is(markEffect)) deco = e.value && e.value.end > e.value.start ? Decoration.set([Decoration.mark({ class: 'executing-word' }).range(e.value.start, e.value.end)]) : Decoration.none; return deco; }, provide: field => EditorView.decorations.from(field) });
const language = StreamLanguage.define({ token(stream) { if (stream.match(/#.*/)) return 'comment'; if (stream.match(/[\[\]]/)) return 'bracket'; if (stream.match(/\b(?:true|false)\b/)) return 'bool'; if (stream.match(/-?\d+/)) return 'number'; if (stream.match(/(?:map|filter|fold|ifte|dip|i)\b/)) return 'keyword'; if (stream.match(/[^\s\[\]#]+/)) return 'variableName'; stream.next(); return null; } });

function persist() { try { localStorage.setItem(KEY, JSON.stringify(saved)); } catch { toast('Local saving is unavailable. Export your workshop to keep it.'); } }
function record() { return saved.lessons[saved.lesson] ||= {}; }
function lesson(): Lesson { return lessons.find(x => x.id === saved.lesson) || worlds.find(x => x.id === saved.lesson) || { id: 'sandbox', title: saved.customName, chapter: 'Laboratory', concept: 'An idea, a few examples, a machine.', story: 'Describe a transformation with examples. Write a program, challenge your assumptions, and keep what you discover.', goal: 'Match your input/output examples. You supply the expected result for each test.', starter: '', examples: saved.examples, discovery: '', review: [], prediction: null, macros: true, source: 'Your examples', extra_tests: 0, hint_count: 1, hints: [] }; }
function payload(code = editor.state.doc.toString()) { return { lesson: saved.lesson, program: code, examples: saved.examples }; }
async function api<T = any>(path: string, data?: unknown): Promise<T> { const response = await fetch(`/api/${path}`, data === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); const body = await response.json(); if (!response.ok) throw Error(body.error || 'The workshop could not complete that action.'); return body; }
function toast(message: string) { $('#toast').textContent = message; $('#toast').classList.add('visible'); setTimeout(() => $('#toast').classList.remove('visible'), 4500); }
function stop() { if (playing) clearInterval(playing); playing = null; const p = $('#play-button'); if (p) { p.innerHTML = `${ic('play')} Play`; icons(); } }
function setCode(code: string) { stop(); editor.dispatch({ changes: { from: 0, to: editor.state.doc.length, insert: code } }); }
function codePrefix() { if (!trace || frame === 0) return ''; return trace.tokens.slice(0, frame).map(t => t.op).join(' '); }
function appendWord(word: string) { const cursor = editor.state.selection.main; const before = editor.state.doc.sliceString(0, cursor.from); const after = editor.state.doc.sliceString(cursor.to); const insert = `${before && !/\s$/.test(before) ? ' ' : ''}${word} `; editor.dispatch({ changes: { from: cursor.from, to: cursor.to, insert }, selection: { anchor: cursor.from + insert.length } }); editor.focus(); }
function noteColor(v: Value) { if (v.type === 'int') { const n = Number(BigInt(v.text) % 360n); return `hsl(${((n * 31 + 175) % 360 + 360) % 360} 70% 72%)`; } return v.type === 'bool' ? '#dbb2fa' : v.type === 'symbol' || v.type === 'mark' ? '#edb971' : '#79c9d3'; }
function signalPlot(current: Value[], target: Value[]) { const values = (s: Value[]) => { const top = s.at(-1); const vs = top?.type === 'list' ? top.items || [] : top ? [top] : []; return vs.every(v => v.type === 'int') ? vs.map(v => Number(v.text)) : []; }; const a = values(current), b = values(target); if (!a.length && !b.length) return ''; const all = [...a, ...b]; if (all.some(x => !Number.isFinite(x))) return ''; const min = Math.min(0, ...all), max = Math.max(1, ...all), span = max - min || 1, count = Math.max(a.length, b.length, 2); const x = (i: number) => 12 + i * 276 / (count - 1), y = (v: number) => 50 - (v - min) / span * 38; const line = (vs: number[]) => vs.map((v, i) => `${x(i)},${y(v)}`).join(' '); return `<div class="signal-view"><div><span>TOP VALUE AS A SIGNAL</span><span><b>—</b> current <em>┄</em> target</span></div><svg viewBox="0 0 300 60" role="img" aria-label="Current top value compared with target, plotted in element order"><line x1="6" x2="294" y1="${y(0)}" y2="${y(0)}" stroke="#647c9040"/><polyline points="${line(b)}" fill="none" stroke="#caa88588" stroke-width="1.4" stroke-dasharray="4 4"/><polyline points="${line(a)}" fill="none" stroke="#8ed1d3" stroke-width="1.6"/>${a.map((v, i) => `<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#8ed1d3"/>`).join('')}${b.map((v, i) => `<circle cx="${x(i)}" cy="${y(v)}" r="4.5" fill="none" stroke="#caa88599"/>`).join('')}</svg></div>`; }
function valueHTML(v: Value, compact = false): string { const children = v.items && !compact ? `<span class="list-bracket">(</span>${v.items.map(x => `<span class="list-item" style="--value-color:${noteColor(x)}">${esc(x.text)}</span>`).join(' ')}<span class="list-bracket">)</span>` : esc(v.text); return `<span class="value value-${v.type}${compact ? ' compact' : ''}" style="--value-color:${noteColor(v)}" title="${esc(v.type)}: ${esc(v.text)}">${children}</span>`; }
function stackHTML(values: Value[], compact = false) { return values.length ? values.map(v => valueHTML(v, compact)).join('') : '<span class="empty-stack">empty stack</span>'; }
let audio: AudioContext | null = null;
function sound(op: string | null, success = false) { if (!saved.sound) return; try { audio ||= new AudioContext(); void audio.resume(); const t = audio.currentTime; const stack = trace?.examples[activeExample]?.frames[Math.min(frame, (trace?.examples[activeExample]?.frames.length || 1) - 1)].stack; const n = Number(stack?.at(-1)?.text || 0); const base = 174.61 * 2 ** ((((Number.isFinite(n) ? Math.abs(n) : 0) % 12)) / 12); const notes = success ? [261.63, 329.63, 392] : [base]; notes.forEach((frequency, i) => { const osc = audio!.createOscillator(), gain = audio!.createGain(); osc.type = op === '[' || op === ']' ? 'triangle' : 'sine'; osc.frequency.value = frequency; gain.gain.setValueAtTime(0, t + i * .075); gain.gain.linearRampToValueAtTime(.035, t + i * .075 + .012); gain.gain.exponentialRampToValueAtTime(.001, t + i * .075 + .19); osc.connect(gain).connect(audio!.destination); osc.start(t + i * .075); osc.stop(t + i * .075 + .21); }); } catch { /* Sound is optional. */ } }

$('#app').innerHTML = `
  <header class="app-header"><a class="brand" href="#" aria-label="Signal House workshop">${ic('layers')}<span>SIGNAL HOUSE<small>STACK WORKSHOP</small></span></a><div class="header-center"><span class="status-light"></span><span>Local workbench</span><span class="divider">/</span><span id="chapter-label">Wake the house</span></div><div class="header-actions"><button data-action="palette" class="command-trigger">${ic('command')} Commands <kbd>Ctrl K</kbd></button><button data-action="sound" id="sound-toggle" class="icon-button" aria-label="Toggle sound"></button><button data-action="settings" class="icon-button" aria-label="Settings">${ic('settings-2')}</button></div></header>
  <div class="app-layout"><aside class="curriculum" aria-label="Workshop curriculum"><div class="rail-heading">THE REPAIR LOG <span id="progress-count">0 / 14</span></div><div class="house-progress" aria-label="Workshop progress"><div id="progress-fill"></div></div><nav id="lesson-nav"></nav><div class="rail-footer"><button data-action="sandbox">${ic('flask-conical')} Free laboratory ${ic('arrow-right')}</button><button data-action="world">${ic('radio')} The world outside <span class="count">183</span></button><p>Your work stays on this computer.</p></div></aside>
  <main class="workspace"><div id="lesson-heading"></div><div class="bench"><section class="program-panel" aria-label="Program editor"><div class="panel-heading"><span>${ic('command')} PROGRAM</span><div><button data-action="vim" id="vim-toggle" class="tiny-button"></button><button data-action="save-fragment" class="icon-button small" aria-label="Save program to notebook">${ic('save')}</button></div></div><div id="editor"></div><div id="program-foot"><span id="code-metrics">mark-28</span><button data-action="complete" class="text-button">Complete <kbd>Ctrl Space</kbd></button></div><div class="execution-toolbar"><button data-action="back" class="icon-button" aria-label="Step backward" title="Step backward (Alt Left)">${ic('skip-back')}</button><button data-action="play" id="play-button">${ic('play')} Play</button><button data-action="step" title="Step forward (Alt Right)">Step ${ic('chevron-right')}</button><button data-action="run" class="run-button" title="Run to end (Ctrl Enter)">Run ${ic('corner-down-left')}</button></div></section><section class="machine-panel" aria-label="Live stack"><div class="panel-heading"><span>${ic('layers')} LIVE MACHINE</span><label>Example <select id="example-select" aria-label="Active example"></select></label></div><div id="machine-stage"></div><div class="machine-bottom"><div class="legend"><span class="legend-int">● number</span><span class="legend-bool">● boolean</span><span class="legend-code">● code</span></div><button data-action="inspect" class="text-button">Enter instruction ${ic('maximize-2')}</button></div></section></div>
  <section class="timeline-panel" aria-label="Execution timeline"><div class="timeline-label"><span>EXECUTION</span><span id="frame-label">INPUT</span><span id="busy-label"></span></div><div id="timeline"></div><input id="scrubber" type="range" min="0" max="0" value="0" aria-label="Execution step"></section>
  <section class="examples-panel" aria-label="Input and output examples"><div class="section-heading"><h2>Make the examples agree</h2><div><button data-action="edit-examples" id="edit-examples" class="text-button">Edit examples</button><span id="matches-label"></span></div></div><div id="examples"></div><div class="check-row"><span id="test-description"></span><button data-action="verify" id="verify-button" class="primary-button">Check repair ${ic('arrow-right')}</button></div><div id="verification" aria-live="polite"></div></section>
  <footer class="workspace-footer"><span><kbd>Alt ← →</kbd> step through time</span><span><kbd>Ctrl Enter</kbd> run</span><span><kbd>Ctrl W</kbd> then <kbd>h j k l</kbd> change pane</span><button data-action="help" class="text-button">All keys <kbd>?</kbd></button></footer></main>
  <aside class="inspector" aria-label="Learning tools"><div class="shelf-tabs" role="tablist"><button role="tab" data-tab="words">${ic('book-open')} Words</button><button role="tab" data-tab="guide">${ic('lightbulb')} Guide</button><button role="tab" data-tab="notebook">${ic('save')} Notes</button></div><div id="shelf"></div></aside></div>
  <div id="toast" role="status"></div><dialog id="modal"><div class="modal-head"><h2 id="modal-title"></h2><button data-action="close-modal" class="icon-button" aria-label="Close dialog">${ic('x')}</button></div><div id="modal-content"></div></dialog>`;

const editor = new EditorView({ parent: $('#editor'), state: EditorState.create({ doc: '', extensions: [basicSetup, vimConfig.of(saved.vim ? vim() : []), language, closeBrackets(), syntaxHighlighting(HighlightStyle.define([{ tag: tags.comment, color: '#8794a4', fontStyle: 'italic' }, { tag: tags.number, color: '#8cd8d1' }, { tag: tags.bool, color: '#d4b1f8' }, { tag: tags.keyword, color: '#f3b174' }, { tag: tags.bracket, color: '#b8a7e5' }, { tag: tags.variableName, color: '#e4ebf0' }])), markField,
  EditorView.theme({ '&': { height: '100%', backgroundColor: 'transparent', color: '#e3eaf2', fontSize: '17px' }, '.cm-content': { fontFamily: "'Cascadia Code', 'Consolas', monospace", padding: '22px 0', minHeight: '215px', caretColor: '#f6b67d' }, '.cm-gutters': { backgroundColor: 'transparent', color: '#69788b', border: 'none', paddingRight: '14px' }, '.cm-line': { padding: '0 18px 0 5px', lineHeight: '1.85' }, '.cm-activeLine, .cm-activeLineGutter': { backgroundColor: '#ffffff04' }, '&.cm-focused': { outline: 'none' }, '.cm-selectionBackground': { backgroundColor: '#345268 !important' }, '.cm-cursor': { borderLeftColor: '#f6b67d' }, '.cm-tooltip': { backgroundColor: '#212c39', color: '#e7edf5', border: '1px solid #46566d', borderRadius: '8px' }, '.cm-tooltip-autocomplete ul li[aria-selected]': { backgroundColor: '#344c5c', color: '#fff' } }, { dark: true }),
  autocompletion({ override: [context => { const word = context.matchBefore(/[^\s\[\]#]*/); if (!word || (!context.explicit && word.from === word.to)) return null; return { from: word.from, options: [...ops.map(op => ({ label: op.name, type: 'function', detail: op.effect, info: () => completionInfo(op), apply: op.name })), ...(lesson().macros ? macros.map(m => ({ label: m.name, type: 'variable', detail: `macro · ${m.group}`, info: `${m.body}\n\nExpands to ${m.expanded.split(' ').length} primitive instructions.` })) : [])] }; }], activateOnTyping: true }), keymap.of(completionKeymap), EditorView.contentAttributes.of({ 'aria-label': 'Stack program', spellcheck: 'false' }),
  EditorView.updateListener.of(update => { if (update.docChanged) { stop(); record().code = update.state.doc.toString(); persist(); verification = null; parseError = ''; pending = true; ++requestId; clearTimeout(evalTimer); evalTimer = setTimeout(() => void evaluate(true), 100); $('#busy-label').textContent = 'Updating…'; $('#verification').innerHTML = ''; } if (update.selectionSet) { const head = update.state.selection.main.head; const word = update.state.wordAt(head); if (word) { const name = update.state.sliceDoc(word.from, word.to); if (ops.some(o => o.name === name) || macros.some(o => o.name === name)) { selectedOp = name; renderWordDetail(); } } } }) ] }) });

function completionInfo(op: Op) { const dom = document.createElement('div'); dom.className = 'completion-info'; dom.innerHTML = `<strong>${esc(op.name)}</strong><p>${esc(op.description)}</p><code>${esc(op.effect)}</code><p class="preview-result">Previewing your examples…</p>`; const prefix = editor.state.doc.sliceString(0, editor.state.selection.main.from).replace(/[^\s\[\]#]*$/, ''); void api<Trace>('preview', { ...payload(prefix), candidate: op.name }).then(data => { dom.querySelector('.preview-result')!.textContent = data.examples.map((r, i) => `${i + 1}: ${r.error || r.output}`).join('\n'); }).catch(e => { dom.querySelector('.preview-result')!.textContent = e.message; }); return dom; }

async function evaluate(toEnd = false) { const id = ++requestId; const currentLesson = saved.lesson; pending = true; try { const result = await api<Trace>('evaluate', payload()); if (id !== requestId || currentLesson !== saved.lesson) return; trace = result; parseError = ''; frame = toEnd ? Math.max(...result.examples.map(r => r.frames.length - 1)) : Math.min(frame, result.tokens.length); activeExample = Math.min(activeExample, result.examples.length - 1); } catch (e) { if (id !== requestId) return; parseError = (e as Error).message; trace = null; frame = 0; } finally { if (id === requestId) { pending = false; renderMachine(); renderTimeline(); renderExamples(); renderWordDetail(); } } }

function selectLesson(id: string) { record().code = editor.state.doc.toString(); saved.lesson = id; record(); persist(); ++requestId; ++adviserSerial; stop(); trace = null; frame = 0; activeExample = 0; hintText = ''; verification = null; $('#verification').innerHTML = ''; selectedOp = id === 'first-light' ? 'add' : id === 'vocabulary' ? 'sum' : 'dup'; renderNav(); renderHeading(); renderShelf(); setCode(record().code ?? lesson().starter); clearTimeout(evalTimer); void evaluate(false); }
function completed() { return lessons.filter(x => saved.lessons[x.id]?.solved).length; }
function renderNav() { const count = completed(); $('#progress-count').textContent = `${count} / ${lessons.length}`; $('#progress-fill').style.width = `${count / Math.max(1, lessons.length) * 100}%`; let chapter = ''; $('#lesson-nav').innerHTML = lessons.map((x, i) => { const head = x.chapter !== chapter ? `<div class="chapter-heading">${esc(x.chapter)}</div>` : ''; chapter = x.chapter; const done = saved.lessons[x.id]?.solved; return `${head}<button class="lesson-link ${saved.lesson === x.id ? 'active' : ''} ${done ? 'done' : ''}" data-lesson="${esc(x.id)}" ${saved.lesson === x.id ? 'aria-current="step"' : ''}><span class="lesson-number">${done ? ic('check') : String(i + 1).padStart(2, '0')}</span><span>${esc(x.title)}</span>${saved.lesson === x.id ? '<span class="active-mark"></span>' : ''}</button>`; }).join(''); icons(); }
function renderHeading() { const x = lesson(), number = lessons.findIndex(l => l.id === x.id); $('#chapter-label').textContent = x.chapter.replace(/^\d+ · /, ''); $('#lesson-heading').innerHTML = `<div class="lesson-overline"><span>${number >= 0 ? `REPAIR ${String(number + 1).padStart(2, '0')}` : x.id === 'sandbox' ? 'OPEN EXPERIMENT' : 'WORLD TASK'}</span><span>${esc(x.concept)}</span>${record().solved ? `<span class="repaired">${ic('check')} Repaired</span>` : ''}</div><h1>${esc(x.title)}</h1><p class="story">${esc(x.story)}</p><div class="mission">${ic('radio')}<span>${esc(x.goal)}</span></div>`; $('#test-description').textContent = x.extra_tests ? `${x.examples.length} visible examples · ${x.extra_tests} extra tests on check` : 'Matches establish a fit to your examples.'; $('#edit-examples').hidden = x.id !== 'sandbox'; $('#vim-toggle').textContent = saved.vim ? 'VIM ON' : 'VIM OFF'; $('#sound-toggle').innerHTML = ic(saved.sound ? 'volume-2' : 'volume-x'); $('#sound-toggle').setAttribute('aria-pressed', String(saved.sound)); document.body.classList.toggle('reduce-motion', !saved.motion); icons(); }

function renderMachine() { $('#busy-label').textContent = pending ? 'Updating…' : parseError ? 'Needs a repair' : 'Live'; $('#code-metrics').textContent = trace ? `${trace.primitive_count} primitive ${trace.primitive_count === 1 ? 'instruction' : 'instructions'} · mark-28` : 'mark-28'; $('#example-select').innerHTML = (trace?.examples || lesson().examples).map((_, i) => `<option value="${i}" ${i === activeExample ? 'selected' : ''}>${String(i + 1).padStart(2, '0')}</option>`).join(''); if (!trace) { $('#machine-stage').innerHTML = `<div class="machine-message"><span class="machine-eyebrow">${parseError ? 'REPAIR NEEDED' : 'READY WHEN YOU ARE'}</span><p>${esc(parseError || 'Write an instruction to watch the stack change.')}</p></div>`; return; }
  const row = trace.examples[activeExample], f = row.frames[Math.min(frame, row.frames.length - 1)], before = row.frames[Math.max(0, Math.min(frame - 1, row.frames.length - 1))];
  const open = f.quoting ?? f.stack.some(v => v.type === 'mark'); const top = trace.tokens[frame - 1];
  $('#machine-stage').innerHTML = `<div class="machine-state-heading"><span class="machine-eyebrow">${f.error ? 'INSTRUCTION REFUSED' : frame === 0 ? 'INPUT STACK' : open ? 'BUILDING A QUOTATION' : 'AFTER'} ${frame && !f.error ? `<strong>${esc(f.op)}</strong>` : ''}</span><span class="fuel">${f.fuel} fuel</span></div><div class="stack-space"><div class="stack-rail">${stackHTML(f.stack)}</div><div class="stack-orientation"><span>deeper</span><span>top ${ic('arrow-right')}</span></div></div><div class="effect-explanation ${f.error ? 'error' : ''}">${f.error ? `${ic('unplug')} ${esc(f.error)}` : frame === 0 ? 'Instructions read from the right. Watch what stays and what is consumed.' : open && f.op !== '[' ? `${esc(f.op)} is captured as code. It has not executed.` : esc(ops.find(o => o.name === f.op)?.description || '')}</div>${frame > 0 && !f.error ? `<div class="before-row"><span>BEFORE</span><div>${stackHTML(before.stack, true)}</div></div>` : ''}${top?.macro ? `<div class="macro-origin">Inside <button data-word="${esc(top.macro)}">${esc(top.macro)}</button> · expanded into primitive instructions</div>` : ''}`;
  $('#machine-stage').insertAdjacentHTML('beforeend', signalPlot(f.stack, row.target));
  if (saved.motion && frame > 0) { const elements = $('#machine-stage').querySelectorAll<HTMLElement>('.stack-rail > .value'); elements.forEach((el, i) => el.animate([{ opacity: .35, transform: 'translateY(5px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: 170, delay: Math.min(i * 12, 60), easing: 'ease-out' })); }
  const t = trace.tokens[frame - 1]; editor.dispatch({ effects: markEffect.of(t ? { start: t.start, end: t.end } : null) }); icons(); }
function renderTimeline() { const max = trace ? Math.max(...trace.examples.map(r => r.frames.length - 1)) : 0; $('#frame-label').textContent = frame === 0 ? 'INPUT' : `${frame} / ${trace?.tokens.length || 0}`; const range = $<HTMLInputElement>('#scrubber'); range.max = String(max); range.value = String(frame); const tokens = trace?.tokens || []; const windowStart = Math.max(0, frame - 22), windowEnd = Math.min(tokens.length, Math.max(44, frame + 22)); $('#timeline').innerHTML = `<button data-frame="0" class="timeline-token ${frame === 0 ? 'current' : ''}" aria-label="Initial state">in</button>${windowStart ? '<span class="timeline-ellipsis">…</span>' : ''}${tokens.slice(windowStart, windowEnd).map((t, offset) => { const i = windowStart + offset; return `<button data-frame="${i + 1}" class="timeline-token ${frame === i + 1 ? 'current' : i < frame ? 'past' : ''}" ${i >= max ? 'disabled' : ''} title="Step ${i + 1}${t.macro ? ` · ${esc(t.macro)}` : ''}">${esc(t.op)}</button>`; }).join('')}${windowEnd < tokens.length ? '<span class="timeline-ellipsis">…</span>' : ''}`; }
function renderExamples() { if (!trace) { $('#examples').innerHTML = `<p class="empty-message">${esc(parseError || 'Preparing example stacks…')}</p>`; $('#matches-label').textContent = ''; return; } $('#matches-label').innerHTML = `<span class="match-count ${trace.matches === trace.count ? 'all' : ''}">${trace.matches} / ${trace.count} match at end</span>`; $('#examples').innerHTML = `<div class="example-row example-labels"><span>CASE</span><span>INPUT</span><span>AT STEP ${frame}</span><span>TARGET</span><span></span></div>${trace.examples.map((r, i) => `<button class="example-row ${i === activeExample ? 'selected' : ''}" data-example="${i}"><span class="case-number">${String(i + 1).padStart(2, '0')}</span><span class="example-stack">${stackHTML(r.input, true)}</span><span class="example-stack">${stackHTML(r.frames[Math.min(frame, r.frames.length - 1)].stack, true)}</span><span class="example-stack">${stackHTML(r.target, true)}</span><span class="example-result ${r.matched ? 'good' : ''}">${r.matched ? ic('check') : '—'}</span></button>`).join('')}`; icons(); }
function setFrame(n: number, audible = true) { if (pending || !trace) return; const max = Math.max(...trace.examples.map(r => r.frames.length - 1)); frame = Math.max(0, Math.min(max, n)); renderMachine(); renderTimeline(); renderExamples(); renderWordDetail(); if (audible) sound(trace.tokens[frame - 1]?.op || null); }
async function runToEnd() { stop(); clearTimeout(evalTimer); await evaluate(true); if (trace) sound(trace.tokens.at(-1)?.op || null); }
async function play() { if (playing) { stop(); return; } if (pending) { await evaluate(); } if (!trace) return; const max = Math.max(...trace.examples.map(r => r.frames.length - 1)); if (frame >= max) setFrame(0, false); $('#play-button').innerHTML = `${ic('pause')} Pause`; icons(); playing = setInterval(() => { if (frame >= max || pending) stop(); else setFrame(frame + 1); }, 520); }

function renderShelf() { document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b => { const active = b.dataset.tab === shelfTab; b.classList.toggle('selected', active); b.setAttribute('aria-selected', String(active)); }); if (shelfTab === 'words') { $('#shelf').innerHTML = `<div class="shelf-intro"><h2>A small vocabulary.<br>A lot of possibilities.</h2><p>Inspect a word. Preview its effect. Try it on the stack.</p></div><label class="word-search">${ic('search')}<input id="word-search" placeholder="Find a word…" aria-label="Search instructions and macros"></label><div id="word-list"></div><div id="word-detail"></div>`; renderWordList(); renderWordDetail(); $('#word-search').addEventListener('input', () => renderWordList()); } else if (shelfTab === 'guide') { renderGuide(); } else { $('#shelf').innerHTML = `<div class="shelf-intro"><h2>Your field notes</h2><p>A place for the patterns you discover.</p></div><label class="field-label" for="lesson-note">THIS REPAIR</label><textarea id="lesson-note" class="note-input" placeholder="What made this work? What surprised you?">${esc(record().note || '')}</textarea><button data-action="save-fragment" class="wide-button">${ic('save')} Keep current program</button><div class="field-label">SAVED PROGRAMS</div><div class="saved-fragments">${saved.shelf.length ? saved.shelf.map((s, i) => `<button data-fragment="${i}"><strong>${esc(s.name)}</strong><code>${esc(s.code.slice(0, 150))}</code></button>`).join('') : '<p>No fragments yet. Save a useful program to revisit it.</p>'}</div><div class="notebook-actions"><button data-action="export">${ic('download')} Export workshop</button><button data-action="import">${ic('upload')} Import</button></div>`; $('#lesson-note').addEventListener('input', e => { record().note = (e.target as HTMLTextAreaElement).value; persist(); }); } icons(); }
function availableOps() { const i = lessons.findIndex(x => x.id === saved.lesson); if (i < 0 || i >= 12) return ops; const names = i < 4 ? ['0', '1', 'dup', 'drop', 'swap', 'over', 'add', 'sub', 'mul'] : i < 6 ? ['0', '1', 'dup', 'drop', 'swap', 'over', 'add', 'sub', 'mul', '[', ']', 'i', 'map'] : null; return names ? ops.filter(o => names.includes(o.name)) : ops; }
function renderWordList() { const el = $('#word-list'); if (!el) return; const query = $<HTMLInputElement>('#word-search').value.toLowerCase(); const words = query ? ops.filter(o => `${o.name} ${o.description}`.toLowerCase().includes(query)) : availableOps(); const ms = lesson().macros || query ? macros.filter(m => `${m.name} ${m.group}`.toLowerCase().includes(query)) : []; el.innerHTML = `<div class="field-label">${query ? 'INSTRUCTIONS' : 'ON YOUR WORKBENCH'}</div><div class="word-chips">${words.map(o => `<button data-word="${esc(o.name)}" class="${o.name === selectedOp ? 'chosen' : ''}">${esc(o.name)}</button>`).join('')}</div>${ms.length ? `<div class="field-label macro-label">CANONICAL MACROS · ${ms.length}</div><div class="word-chips macro-chips">${ms.map(m => `<button data-word="${esc(m.name)}" class="${m.name === selectedOp ? 'chosen' : ''}">${esc(m.name)}</button>`).join('')}</div>` : ''}`; }
function renderWordDetail() { const el = $('#word-detail'); if (!el || shelfTab !== 'words') return; const op = ops.find(o => o.name === selectedOp), macro = macros.find(m => m.name === selectedOp); if (!op && !macro) return; const name = op?.name || macro!.name; el.innerHTML = `<div class="word-card"><div class="word-card-heading"><strong>${esc(name)}</strong><span>${macro ? 'MACRO' : esc(op!.group).toUpperCase()}</span></div>${op ? `<code class="stack-effect">${esc(op.effect)}</code><p>${esc(op.description)}</p>` : `<p>A named pattern from the canonical library.</p><code class="macro-body">${esc(macro!.body)}</code><details><summary>${macro!.expanded.split(' ').length} primitive instructions</summary><code class="macro-body">${esc(macro!.expanded)}</code></details>`}<div id="word-preview" class="word-preview">${pending ? 'Updating the stack…' : 'Preview on your current timeline state'}</div><button class="wide-button" data-insert="${esc(name)}">Insert ${esc(name)} ${ic('corner-down-left')}</button><p class="small-note">Preview uses step ${frame}. Insert writes at your editor cursor.</p></div>`; icons(); clearTimeout(completionTimer); const serial = ++previewSerial; completionTimer = setTimeout(async () => { if (pending || !trace) return; try { const data = await api<Trace>('preview', { ...payload(codePrefix()), candidate: name }); if (serial !== previewSerial || !$('#word-preview')) return; $('#word-preview').innerHTML = data.examples.slice(0, 3).map((r, i) => `<div><span>${String(i + 1).padStart(2, '0')}</span><code class="${r.error ? 'preview-error' : ''}">${esc(r.error || r.output)}</code></div>`).join(''); } catch (e) { if (serial === previewSerial && $('#word-preview')) $('#word-preview').textContent = (e as Error).message; } }, 140); }

function renderGuide() { const x = lesson(), r = record(); const reviews = x.review.map(id => lessons.find(l => l.id === id)).filter(Boolean) as Lesson[]; $('#shelf').innerHTML = `<div class="shelf-intro"><h2>Observe. Predict. Repair.</h2><p>Try an idea, then let the machine explain what happened.</p></div>${x.prediction ? `<div class="guide-card"><span class="field-label">BEFORE YOU RUN</span><p>${esc(x.prediction)}</p><input id="prediction" value="${esc(r.prediction || '')}" placeholder="Your prediction…" aria-label="Your prediction"><p class="small-note">Keep your prediction, then compare it with the live trace.</p></div>` : ''}<div class="guide-card"><div class="word-card-heading"><strong>A little direction</strong><span>${Math.min(r.hints || 0, x.hint_count)} / ${x.hint_count}</span></div><p id="hint-text">${esc(hintText || 'Ask for a conceptual nudge when you need one. You decide how much to reveal.')}</p><button data-action="hint" class="wide-button">${ic('lightbulb')} ${r.hints ? 'Another nudge' : 'Give me a nudge'}</button><button data-action="reveal" class="text-button reveal">Reveal a reference program</button></div>${reviews.length ? `<div class="guide-card"><span class="field-label">BRING THESE IDEAS BACK</span><p>Recall the earlier repair before rereading it.</p>${reviews.map(x => `<button class="review-link" data-lesson="${esc(x.id)}">${esc(x.title)} ${ic('arrow-right')}</button>`).join('')}</div>` : ''}<div class="guide-card model-card"><div class="word-card-heading"><strong>${ic('sparkles')} Trained adviser</strong><span id="model-status">${model.ready ? 'CONNECTED' : 'OPTIONAL'}</span></div><p>Ask the policy for possible next instructions from step ${frame}.</p><button data-action="suggest" class="wide-button">${ic('sparkles')} Suggest a next move</button><div id="suggestions"></div><p class="small-note">Rankings reflect the trained policy, not certainty or a proof. You remain the solver.</p><button data-action="model-settings" class="text-button">${model.ready ? 'Checkpoint details' : 'Connect a checkpoint'}</button></div>`; if ($('#prediction')) $('#prediction').addEventListener('input', e => { r.prediction = (e.target as HTMLInputElement).value; persist(); }); icons(); }

async function checkRepair() { stop(); clearTimeout(evalTimer); await evaluate(true); if (parseError || !trace) return; const id = saved.lesson, code = editor.state.doc.toString(); record().attempts = (record().attempts || 0) + 1; const button = $('#verify-button') as HTMLButtonElement; button.disabled = true; button.textContent = 'Checking…'; try { const result = await api<Verify>('verify', payload()); if (id !== saved.lesson || code !== editor.state.doc.toString()) return; verification = result; if (result.passed) { const wasSolved = !!record().solved; record().solved = true; record().saved = code; record().reviewed = completed(); if (!wasSolved) sound(null, true); persist(); renderNav(); renderHeading(); } renderVerification(); } catch (e) { toast((e as Error).message); } finally { button.disabled = false; button.innerHTML = `Check repair ${ic('arrow-right')}`; icons(); } }
function renderVerification() { if (!verification) return; const v = verification, x = lesson(); const next = lessons[lessons.findIndex(l => l.id === saved.lesson) + 1]; $('#verification').innerHTML = `<div class="verification ${v.passed ? 'success' : 'needs-work'}"><div class="verification-icon">${ic(v.passed ? 'check' : 'search')}</div><div><h3>${v.passed ? saved.lesson === 'sandbox' ? 'These examples agree.' : 'The signal is getting through.' : 'There is something to investigate.'}</h3><p>${v.passed ? esc(x.discovery || 'Your program matches every supplied example. Add a new test to challenge your hypothesis.') : `${v.shown} / ${v.shown_count} shown examples and ${v.extra} / ${v.extra_count} extra tests pass.`}</p>${v.failures.map(r => `<div class="counterexample"><span>COUNTEREXAMPLE</span><code>${esc(r.input.map(v => v.text).join(' '))} → ${esc(r.output)}</code><span>Expected ${esc(r.target.map(v => v.text).join(' '))}</span></div>`).join('')}${v.passed && next ? `<button data-lesson="${next.id}">Next repair: ${esc(next.title)} ${ic('arrow-right')}</button>` : v.passed && saved.lesson === 'outgoing' ? `<button data-action="world">Open the world shelf ${ic('arrow-right')}</button>` : ''}</div></div>`; icons(); }

function modal(title: string, content: string) { stop(); lastFocused = document.activeElement as HTMLElement; $('#modal-title').textContent = title; $('#modal-content').innerHTML = content; const d = $<HTMLDialogElement>('#modal'); if (!d.open) d.showModal(); icons(); }
function closeModal() { $<HTMLDialogElement>('#modal').close(); lastFocused?.focus(); }
function help() { modal('Everything from the keyboard', `<p class="modal-intro">Vim applies inside the editor. App shortcuts work across the workbench.</p><div class="key-table">${[['Ctrl K', 'Search commands, repairs, and words'], ['Ctrl Enter', 'Run the program to the end'], ['Ctrl Shift Enter', 'Check the repair and extra tests'], ['Alt → / Alt ←', 'Step forward / backward'], ['Alt Home', 'Return to the input stack'], ['Alt I', 'Enter the current instruction'], ['Alt H', 'Ask for a nudge'], ['Ctrl Space', 'Open code completion'], ['Ctrl W, then h / l', 'Focus the previous / next pane'], ['Ctrl W, then j / k', 'Focus examples / editor'], ['Escape', 'Close a dialog or return to Vim normal mode'], [':run / :step / :back', 'Vim execution commands'], [':hint / :check / :next', 'Vim learning commands'], ['Tab / Shift Tab', 'Reach every button, field, and pane']].map(([k, t]) => `<div><kbd>${k}</kbd><span>${t}</span></div>`).join('')}</div><p class="small-note">In a browser, Ctrl W may be reserved for closing a tab. Alt 1 / 2 / 3 / 4 always focuses the repair log, editor, examples, or learning tools.</p>`); }
function settings() { modal('Tune your workbench', `<div class="setting"><div><strong>Vim editing</strong><p>Normal, insert, visual modes, motions, and commands.</p></div><input id="setting-vim" type="checkbox" ${saved.vim ? 'checked' : ''} aria-label="Use Vim editing"></div><div class="setting"><div><strong>Hear the stack</strong><p>Numbers have a stable pitch and color. Quotations use a softer triangle tone. No information relies on sound.</p></div><input id="setting-sound" type="checkbox" ${saved.sound ? 'checked' : ''} aria-label="Enable sound"></div><div class="setting"><div><strong>Motion</strong><p>Short transitions connect one stack state to the next.</p></div><input id="setting-motion" type="checkbox" ${saved.motion ? 'checked' : ''} aria-label="Enable motion"></div><button data-action="model-settings" class="wide-button">${ic('sparkles')} Trained policy connection</button><div class="modal-actions"><button data-action="apply-settings" class="primary-button">Save preferences</button></div>`); }
function modelSettings() { modal('Connect the trained adviser', `<p class="modal-intro">The workshop runs without a model. The adviser uses the existing mark-28 policy to rank your next instructions.</p><p class="connection-state">${model.ready ? 'Connected to ' + esc(model.checkpoint) : model.loading ? 'Loading…' : 'No checkpoint connected.'}</p><label class="field-label" for="checkpoint-path">LOCAL CHECKPOINT FOLDER</label><input id="checkpoint-path" class="full-input" placeholder="D:\\…\\2m-s1" value="${esc(model.checkpoint || '')}"><div class="modal-actions"><button data-action="load-checkpoint">Load folder</button><button data-action="download-checkpoint" class="primary-button">Download archived 2m-s1</button></div><p id="model-feedback" class="small-note">${esc(model.error || 'The archive may require your W&B login. Model files are cached locally; examples stay on this machine.')}</p>`); }
async function connectModel(download: boolean) { const feedback = $('#model-feedback'); if (!feedback) return; feedback.textContent = 'Loading the checkpoint. You can close this dialog and keep working.'; document.querySelectorAll<HTMLButtonElement>('[data-action="load-checkpoint"], [data-action="download-checkpoint"]').forEach(x => x.disabled = true); try { model = await api<Model>('model/load', { download, checkpoint: $<HTMLInputElement>('#checkpoint-path').value.trim() || undefined }); if ($('#model-feedback')) $('#model-feedback').textContent = model.ready ? 'Connected. Open Guide to ask for a next move.' : model.error || 'Could not load checkpoint.'; toast(model.ready ? 'The trained adviser is connected.' : model.error || 'Checkpoint unavailable.'); if (shelfTab === 'guide') renderGuide(); } catch (e) { if ($('#model-feedback')) $('#model-feedback').textContent = (e as Error).message; } finally { document.querySelectorAll<HTMLButtonElement>('[data-action="load-checkpoint"], [data-action="download-checkpoint"]').forEach(x => x.disabled = false); } }
async function suggest() { if (shelfTab !== 'guide') { shelfTab = 'guide'; renderShelf(); } if (!model.ready) { modelSettings(); return; } if (pending) await evaluate(); const serial = ++adviserSerial; $('#suggestions').innerHTML = '<p class="small-note">Reading your example stacks…</p>'; const step = frame; try { const r = await api('suggest', payload(codePrefix())); if (serial !== adviserSerial || !$('#suggestions')) return; $('#suggestions').innerHTML = `<div class="field-label">SUGGESTED AT STEP ${step}</div>${r.suggestions.map((s: any) => `<button class="suggestion" data-insert="${esc(s.op)}"><code>${esc(s.op)}</code><span>${(s.probability * 100).toFixed(1)}% policy weight</span><small>${esc(s.previews[activeExample])}</small></button>`).join('')}<p class="small-note">Inserting writes at the editor cursor. Move it to the corresponding point if you are exploring an earlier state.</p>`; record().assisted = true; persist(); } catch (e) { if ($('#suggestions')) $('#suggestions').textContent = (e as Error).message; } }
async function nudge() { const id = saved.lesson; const r = record(); const data = await api('hint', { ...payload(), level: r.hints || 0 }); if (saved.lesson !== id) return; r.hints = Math.min((r.hints || 0) + 1, lesson().hint_count); r.assisted = true; hintText = data.text; persist(); shelfTab = 'guide'; renderShelf(); }
async function reveal() { modal('Open a reference program?', `<p class="modal-intro">Your current program will stay in the notebook. You can step through the reference and compare its approach with yours.</p><div class="modal-actions"><button data-action="close-modal">Keep exploring</button><button data-action="confirm-reveal" class="primary-button">Open reference</button></div>`); }
async function confirmReveal() { const id = saved.lesson; const r = await api('reveal', payload()); if (id !== saved.lesson) return; if (editor.state.doc.toString().trim()) saved.shelf.push({ name: `${lesson().title} · my attempt`, code: editor.state.doc.toString() }); record().assisted = true; closeModal(); setCode(r.program); persist(); toast('Reference opened. Step through it to follow the idea.'); }
async function inspect() { if (!trace || !frame) { toast('Step onto an instruction first, then enter it.'); return; } const result = await api('inspect', { ...payload(), step: frame - 1, example: activeExample }); modal(`Inside ${trace.tokens[frame - 1].op}`, `<p class="modal-intro">Actual machine calls, in completion order. Indentation shows quotation depth. Example ${activeExample + 1}.</p><div class="inner-trace">${result.frames.map((f: any) => `<div class="inner-frame" style="--depth:${Math.min(f.depth, 8)}"><code>${esc(f.op)}</code><div class="inner-stacks"><div>${stackHTML(f.before, true)}</div><span>↓</span><div>${stackHTML(f.after, true)}</div></div>${f.error ? `<p class="error">${esc(f.error)}</p>` : ''}</div>`).join('')}</div>${result.truncated ? '<p>Showing the first 350 completed calls.</p>' : ''}`); }
function editExamples() { modal('Your PBE experiment', `<p class="modal-intro">Enter JSON examples. The outer array is the stack, deepest first. A list is nested inside it. Booleans are supported.</p><label class="field-label" for="experiment-name">EXPERIMENT NAME</label><input id="experiment-name" class="full-input" value="${esc(saved.customName)}"><label class="field-label" for="example-json">INPUT / OUTPUT PAIRS</label><textarea id="example-json" class="json-input" spellcheck="false">${esc(JSON.stringify(saved.examples, null, 2))}</textarea><p class="small-note">For a list sum: { "input": [[1, 2, 3]], "output": [6] }. Add zero, negatives, and empty inputs to test your interpretation.</p><p id="examples-feedback" class="error" role="alert"></p><div class="modal-actions"><button data-action="apply-examples" class="primary-button">Use these examples</button></div>`); }
async function applyExamples() { try { const examples = JSON.parse($<HTMLTextAreaElement>('#example-json').value); await api('evaluate', { lesson: 'sandbox', program: '', examples }); saved.examples = examples; saved.customName = $<HTMLInputElement>('#experiment-name').value.trim() || 'Untitled experiment'; persist(); closeModal(); if (saved.lesson !== 'sandbox') selectLesson('sandbox'); else { renderHeading(); void evaluate(true); } } catch (e) { $('#examples-feedback').textContent = (e as Error).message; } }
function worldShelf() { modal('The world outside', `<p class="modal-intro">Later material from #118 and the world-authoring work: ${worldAvailable} tasks over integers and lists. Use the canonical macro shelf as a vocabulary.</p>${worlds.length ? '<label class="word-search">' + ic('search') + '<input id="world-search" placeholder="Search behaviours…" aria-label="Search world tasks"></label><div id="world-list"></div>' : '<p>The published corpus will be downloaded to this computer and checked against its committed manifest.</p><button data-action="download-world" class="primary-button">Load world tasks</button><p id="world-feedback"></p>'}`); if (worlds.length) { renderWorldList(); $('#world-search').addEventListener('input', renderWorldList); } }
function renderWorldList() { const q = $<HTMLInputElement>('#world-search').value.toLowerCase(); $('#world-list').innerHTML = [...worlds].sort((a,b)=>(a.primitive_count || 0)-(b.primitive_count || 0)).filter(x => `${x.title} ${x.goal}`.toLowerCase().includes(q)).map(x => `<button class="world-task" data-lesson="${esc(x.id)}"><strong>${esc(x.title)}</strong><span>${esc(x.goal)}</span><small>${x.primitive_count} primitive instructions in reference · ${x.extra_tests} extra tests</small></button>`).join(''); }
async function downloadWorld() { $('#world-feedback').textContent = 'Loading the published corpus…'; try { const result = await api('world', {}); worlds = result.tasks; worldShelf(); } catch (e) { if ($('#world-feedback')) $('#world-feedback').textContent = (e as Error).message; } }
function saveFragment() { modal('Keep a useful program', `<label class="field-label" for="fragment-name">NAME</label><input id="fragment-name" class="full-input" value="${esc(lesson().title)}"><pre class="saved-preview">${esc(editor.state.doc.toString())}</pre><div class="modal-actions"><button data-action="confirm-save" class="primary-button">Save to notebook</button></div>`); }
function exportSave() { const blob = new Blob([JSON.stringify(saved, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = 'signal-house-workshop.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function importSave() { const input = document.createElement('input'); input.type = 'file'; input.accept = '.json'; input.onchange = async () => { try { const file = input.files?.[0]; if (!file || file.size > 2_000_000) throw Error('Choose a workshop JSON file smaller than 2 MB.'); const data = JSON.parse(await file.text()); if (data.version !== 1 || !data.lessons || typeof data.lessons !== 'object' || !Array.isArray(data.shelf) || !Array.isArray(data.examples)) throw Error('This is not a Signal House workshop export.'); saved = { ...defaults, ...data }; persist(); location.reload(); } catch (e) { toast((e as Error).message); } }; input.click(); }
const commandActions = [ ['run', 'Run to end', 'Ctrl Enter'], ['verify', 'Check this repair', 'Ctrl Shift Enter'], ['step', 'Step forward', 'Alt →'], ['back', 'Step backward', 'Alt ←'], ['rewind', 'Return to input', 'Alt Home'], ['inspect', 'Enter instruction', 'Alt I'], ['hint', 'Give me a nudge', 'Alt H'], ['suggest', 'Ask the trained adviser', ''], ['sandbox', 'Open free laboratory', ''], ['world', 'Open world tasks', ''], ['settings', 'Tune the workbench', ''], ['help', 'Keyboard reference', '?'], ['export', 'Export my workshop', ''], ['save-fragment', 'Save program to notebook', ''] ];
function palette() { modal('Find your next action', `<label class="command-search">${ic('search')}<input id="command-query" autocomplete="off" placeholder="Run, repair, word…" aria-label="Search commands"></label><div id="command-results" role="listbox"></div>`); commandIndex = 0; renderCommands(); $('#command-query').addEventListener('input', () => { commandIndex = 0; renderCommands(); }); $('#command-query').addEventListener('keydown', e => { const rows = [...document.querySelectorAll<HTMLButtonElement>('.command-result')]; if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); commandIndex = Math.max(0, Math.min(rows.length - 1, commandIndex + (e.key === 'ArrowDown' ? 1 : -1))); renderCommands(); } else if (e.key === 'Enter') { e.preventDefault(); rows[commandIndex]?.click(); } }); $<HTMLInputElement>('#command-query').focus(); }
function renderCommands() { const query = $<HTMLInputElement>('#command-query').value.toLowerCase(); const rows = [...commandActions.map(([action, name, key]) => ({ name, key, attribute: `data-command="${action}"` })), ...lessons.map(x => ({ name: `Repair · ${x.title}`, key: '', attribute: `data-lesson="${x.id}"` })), ...ops.map(x => ({ name: `Word · ${x.name} — ${x.description}`, key: '', attribute: `data-command-word="${esc(x.name)}"` }))].filter(x => x.name.toLowerCase().includes(query)).slice(0, 24); $('#command-results').innerHTML = rows.length ? rows.map((r, i) => `<button class="command-result ${i === commandIndex ? 'selected' : ''}" ${r.attribute} role="option" aria-selected="${i === commandIndex}"><span>${esc(r.name)}</span><kbd>${esc(r.key)}</kbd></button>`).join('') : '<p>No matching actions.</p>'; document.querySelector('.command-result.selected')?.scrollIntoView({ block: 'nearest' }); }

async function action(name: string) { switch (name) { case 'palette': palette(); break; case 'sound': saved.sound = !saved.sound; persist(); renderHeading(); if (saved.sound) sound('add'); break; case 'vim': saved.vim = !saved.vim; editor.dispatch({ effects: vimConfig.reconfigure(saved.vim ? vim() : []) }); persist(); renderHeading(); editor.focus(); break; case 'settings': settings(); break; case 'apply-settings': saved.vim = $<HTMLInputElement>('#setting-vim').checked; saved.sound = $<HTMLInputElement>('#setting-sound').checked; saved.motion = $<HTMLInputElement>('#setting-motion').checked; editor.dispatch({ effects: vimConfig.reconfigure(saved.vim ? vim() : []) }); persist(); renderHeading(); closeModal(); break; case 'run': await runToEnd(); break; case 'play': await play(); break; case 'step': stop(); if (pending) await evaluate(); setFrame(frame + 1); break; case 'back': stop(); setFrame(frame - 1); break; case 'rewind': stop(); setFrame(0); break; case 'verify': await checkRepair(); break; case 'complete': editor.focus(); startCompletion(editor); break; case 'help': help(); break; case 'inspect': await inspect(); break; case 'hint': await nudge(); break; case 'suggest': await suggest(); break; case 'reveal': await reveal(); break; case 'confirm-reveal': await confirmReveal(); break; case 'close-modal': closeModal(); break; case 'sandbox': selectLesson('sandbox'); break; case 'edit-examples': editExamples(); break; case 'apply-examples': await applyExamples(); break; case 'model-settings': modelSettings(); break; case 'load-checkpoint': await connectModel(false); break; case 'download-checkpoint': await connectModel(true); break; case 'world': worldShelf(); break; case 'download-world': await downloadWorld(); break; case 'save-fragment': saveFragment(); break; case 'confirm-save': saved.shelf.push({ name: $<HTMLInputElement>('#fragment-name').value.trim() || 'A useful pattern', code: editor.state.doc.toString() }); persist(); closeModal(); shelfTab = 'notebook'; renderShelf(); toast('Program kept in your notebook.'); break; case 'export': exportSave(); break; case 'import': importSave(); break; case 'next': { const i = lessons.findIndex(x => x.id === saved.lesson); if (lessons[i + 1]) selectLesson(lessons[i + 1].id); break; } } }
document.addEventListener('click', e => { const b = (e.target as HTMLElement).closest<HTMLElement>('button, a.brand'); if (!b) return; if (b.dataset.command) { const a = b.dataset.command; closeModal(); void action(a).catch(e => toast(e.message)); return; } if (b.dataset.commandWord) { const word = b.dataset.commandWord; closeModal(); shelfTab = 'words'; selectedOp = word; renderShelf(); return; } if (b.dataset.lesson) { if ($<HTMLDialogElement>('#modal').open) closeModal(); selectLesson(b.dataset.lesson); } else if (b.dataset.word) { selectedOp = b.dataset.word; shelfTab = 'words'; if (!$('#word-detail')) renderShelf(); else { renderWordList(); renderWordDetail(); } } else if (b.dataset.insert) appendWord(b.dataset.insert); else if (b.dataset.frame) { stop(); setFrame(Number(b.dataset.frame)); } else if (b.dataset.example) { activeExample = Number(b.dataset.example); renderMachine(); renderExamples(); renderWordDetail(); } else if (b.dataset.tab) { shelfTab = b.dataset.tab; renderShelf(); } else if (b.dataset.fragment) { const fragment = saved.shelf[Number(b.dataset.fragment)]; modal(fragment.name, `<pre class="saved-preview">${esc(fragment.code)}</pre><button class="primary-button" data-load-fragment="${b.dataset.fragment}">Open in editor</button>`); } else if (b.dataset.loadFragment) { const f = saved.shelf[Number(b.dataset.loadFragment)]; closeModal(); setCode(f.code); } else if (b.dataset.action) void action(b.dataset.action).catch(e => toast(e.message)); });
$('#example-select').addEventListener('change', e => { activeExample = Number((e.target as HTMLSelectElement).value); renderMachine(); renderExamples(); renderWordDetail(); });
$('#scrubber').addEventListener('input', e => { stop(); setFrame(Number((e.target as HTMLInputElement).value)); });
$('#modal').addEventListener('close', () => lastFocused?.focus());
function focusPane(which: number) { const panes = [$('.curriculum button'), editor.contentDOM, $('#examples button'), $('#shelf input, #shelf button, #shelf textarea')]; panes[which]?.focus(); }
document.addEventListener('keydown', e => { const modalOpen = $<HTMLDialogElement>('#modal').open; if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); palette(); return; } if (modalOpen) return; if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); e.stopImmediatePropagation(); void action(e.shiftKey ? 'verify' : 'run'); return; } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'w') { e.preventDefault(); focusPrefix = true; setTimeout(() => focusPrefix = false, 1000); return; } if (focusPrefix) { focusPrefix = false; const pane = document.activeElement?.closest('.curriculum') ? 0 : editor.hasFocus ? 1 : document.activeElement?.closest('.examples-panel') ? 2 : 3; const to = e.key === 'h' ? Math.max(0, pane - 1) : e.key === 'l' ? Math.min(3, pane + 1) : e.key === 'j' ? 2 : e.key === 'k' ? 1 : -1; if (to >= 0) { e.preventDefault(); e.stopImmediatePropagation(); focusPane(to); } return; } if (e.altKey) { const mapping: Record<string, string> = { ArrowRight: 'step', ArrowLeft: 'back', Home: 'rewind', i: 'inspect', h: 'hint' }; if (mapping[e.key]) { e.preventDefault(); void action(mapping[e.key]).catch(e => toast(e.message)); } if (/^[1-4]$/.test(e.key)) { e.preventDefault(); focusPane(Number(e.key) - 1); } } if (e.key === '?' && !editor.hasFocus && !['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName)) { e.preventDefault(); help(); } }, true);
for (const [name, a] of [['run', 'run'], ['step', 'step'], ['back', 'back'], ['hint', 'hint'], ['check', 'verify'], ['next', 'next'], ['words', 'complete']]) Vim.defineEx(name, name, () => void action(a));

async function boot() { try { const data = await api('context'); lessons = data.lessons; ops = data.ops; macros = data.macros; model = data.model; worlds = data.world.tasks; worldAvailable = data.world.available; if (!lessons.some(x => x.id === saved.lesson) && !worlds.some(x => x.id === saved.lesson) && saved.lesson !== 'sandbox') saved.lesson = 'first-light'; renderNav(); renderHeading(); renderShelf(); setCode(record().code ?? lesson().starter); clearTimeout(evalTimer); await evaluate(false); // Start on input; editing then updates live to the end.
    frame = 0; renderMachine(); renderTimeline(); renderExamples();
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) { saved.motion = false; renderHeading(); }
    registerWorkshopTools();
  } catch (e) { $('#lesson-heading').innerHTML = `<h1>The workbench is offline.</h1><p>${esc((e as Error).message)}</p><p>Start the local workshop service, then reload this page.</p>`; } }
void boot();

function registerWorkshopTools() {
  const context = (document as Document & { modelContext?: { registerTool: (tool: any, options: any) => unknown } }).modelContext;
  if (!context?.registerTool) return;
  const lifecycle = new AbortController();
  window.addEventListener('pagehide', () => lifecycle.abort(), { once: true });
  const read = () => ({ lesson: saved.lesson, title: lesson().title, program: editor.state.doc.toString(), step: frame, matches: trace?.matches ?? 0, example_count: trace?.count ?? 0, error: parseError || null });
  const definitions = [
    { name: 'read_stack_workshop', title: 'Read the stack workbench', description: 'Read the selected repair, current program, timeline position, and example matches.', inputSchema: { type: 'object', properties: {}, additionalProperties: false }, annotations: { readOnlyHint: true, untrustedContentHint: true }, execute: read },
    { name: 'stage_stack_program', title: 'Stage a stack program', description: 'Replace the current editor program and update its visible execution trace. Does not mark a repair completed.', inputSchema: { type: 'object', properties: { program: { type: 'string', maxLength: 24000 } }, required: ['program'], additionalProperties: false }, annotations: { readOnlyHint: false, untrustedContentHint: true }, async execute(input: unknown) { if (!input || typeof input !== 'object' || Object.keys(input).some(k => k !== 'program') || typeof (input as any).program !== 'string' || (input as any).program.length > 24000) throw Error('Expected a program string of at most 24,000 characters.'); const code = (input as { program: string }).program; const id = saved.lesson; await api('evaluate', payload(code)); if (id !== saved.lesson) throw Error('The selected repair changed; please try again.'); setCode(code); clearTimeout(evalTimer); await evaluate(true); return read(); } },
  ];
  for (const definition of definitions) { try { void Promise.resolve(context.registerTool(definition, { signal: lifecycle.signal })).catch(() => {}); } catch { /* Standard browsers need no agent tools. */ } }
}
